  ? output.supportive_comments
  : Array.isArray(output.comments)
    ? output.comments
    : [];

const seen = new Set();
const commentsArray = [];

for (const entry of rawComments) {
  const value = typeof entry === 'string'
    ? entry
    : entry?.comment_text ?? entry?.comment ?? entry?.text ?? '';
  const comment = String(value)
    .replace(/\s+/g, ' ')
    .trim();

  if (!comment) continue;

  const duplicateKey = comment.toLowerCase();
  if (seen.has(duplicateKey)) continue;
  seen.add(duplicateKey);
  commentsArray.push(comment);
}

if (!Number.isSafeInteger(requestedCommentCount) || requestedCommentCount < 10 || requestedCommentCount > 250) {
  throw new Error('Requested comment amount must be a whole number from 10 to 250.');
}

if (commentsArray.length !== requestedCommentCount) {
  throw new Error(`Expected ${requestedCommentCount} unique supportive comments, but generation returned ${commentsArray.length}.`);
}

const formattedComments = commentsArray.join('\n');

return [{
