if (!/^[0-9]{1,19}$/.test(postId)) {
  errorMessage = 'Usage: /order_comments POST_ID. POST_ID must be 1 to 19 digits.';
} else if (!/^\d+$/.test(amountText)) {
  errorMessage = 'Comment amount must be a whole number from 10 to 250.';
} else {
