}];

// Clear Telegram User Links and Deactivate Tracked Users For Chat both return
// Supabase rows, which do not carry the usersToTrack list that
// Split Users To Track needs. Re-emit the resolved payload so the tracking
// branch keeps its input, and keep pairedItem so downstream
// $('...').item lookups still resolve.
//
// T5: re-emits Build Track Client Result rather than Parse Users To Track, so
// the resolved client_id travels with the accounts instead of being looked up
// again further down.
return [{
  json: $('Build Track Client Result').first().json,
  pairedItem: { item: 0 },
}];

const plan = $('Build Hide Queue Items').first().json || {};
const enqueue = $input.first()?.json || {};

function escapeHtml(value) {
  return String(value === null || value === undefined ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function buildMessage(lines) {
  return lines.filter(function (line) { return line !== ''; }).join('\n');
}

const submitted = Number(enqueue.submitted || plan.submitted || 0);
// Rows already in flight when the button was pressed keep their old batch and
// are not re-armed, so queued can legitimately be lower than submitted.
const queued = Number(enqueue.queued !== undefined ? enqueue.queued : submitted);
const alreadyInFlight = Math.max(0, submitted - queued);
const totalReplies = Number(plan.total_replies || 0);
const locallyAlreadyHidden = Number(plan.locally_already_hidden || 0);

// X allows 50 hides per 15 minutes per account, and the drain runs every 5
// minutes, so quote the honest first-window figure rather than promising the
// whole batch immediately.
const firstWindow = Math.min(queued, 50);
const needsMoreWindows = queued > 50;

const lines = [
  '<b>Hiding replies</b>',
  'Post: <code>' + escapeHtml(plan.post_id) + '</code>',
  'Total stored replies: ' + totalReplies,
