const post = $input.first()?.json || {};

const postId = String(auth.post_id || '');
const postExists = Boolean(post && post.post_id);

// T5: an unknown/inactive client on a staff /track. Checked FIRST and gated on
// an explicit marker set only by Build Track Client Result, so every pre-T5
// branch reaches this node with the marker absent and behaves exactly as before.
const trackClientUnresolved = post.track_client_unresolved === true;

// T5: the client-administration commands are staff-only for the same reason
// /track is -- they change who owns what. Same refusal text, so a client chat
// cannot tell a staff-only command from an unrecognised one.
const STAFF_ONLY_INTENTS = new Set(['TRACK_USERS', 'LIST_CLIENTS', 'CREATE_CLIENT', 'ATTACH_CHAT']);

let refusal_reason;
if (trackClientUnresolved) {
  refusal_reason = 'unknown_client';
} else if (auth.auth_is_known !== true) {
  refusal_reason = 'unknown_chat';
} else if (STAFF_ONLY_INTENTS.has(auth.intent)) {
  refusal_reason = 'staff_only_command';
} else if (postExists) {
  refusal_reason = 'cross_tenant_post';
} else {
  refusal_reason = 'post_not_found';
}

const requestedSlug = String(post.requested_client_slug || '');
const availableSlugs = String(post.available_slugs || '');

const MESSAGES = {
  unknown_chat: {
    message: 'This chat is not registered with XMonitor. Ask your account manager to add it, then try again.',
    callback_text: 'Chat not registered.',
  },
  staff_only_command: {
    message: 'This command is not available for this chat.',
    callback_text: 'Not available.',
  },
  post_denied: {
    message: `Post ${postId} was not found. Wait for monitoring to flag it, then try again.`,
    callback_text: 'Post not found.',
  },
  // Naming the valid slugs is safe here and nowhere else: /track is staff-only,
  // so this message can only ever reach a chat that is already allowed to act
  // across every client. It is not an oracle the way a post id would be.
  unknown_client: {
    message: availableSlugs
      ? `No active client with slug "${requestedSlug}". Active clients: ${availableSlugs}.`
      : `No active client with slug "${requestedSlug}". There are no active clients yet -- create one with /client_new first.`,
    callback_text: 'Unknown client.',
  },
};

const chosen = MESSAGES[refusal_reason] || MESSAGES.post_denied;

return [{
  json: {
    telegram_chat_id: auth.telegram_chat_id,
    callback_query_id: auth.callback_query_id || '',
    callback_message_id: auth.callback_message_id || '',
    post_id: postId,
    intent: auth.intent || '',
    command: auth.command || '',
    refusal_reason,
    denied_post_client_id: postExists ? String(post.client_id || '') : '',
    requested_client_slug: requestedSlug,
    caller_client_ids: auth.auth_client_ids || [],
    caller_is_staff: auth.auth_is_staff === true,
    message: chosen.message,
    callback_text: chosen.callback_text,
  },
}];

// T2: Action Log does not exist yet (it arrives with the Action Executor), so
// refusals are recorded in execution data by Build Access Refusal and escalated
// here. An unknown chat always pings staff so it can be assigned (decision #7).
// Post denials ping only on a repeated pattern from the same chat, which is what
// probing for other clients' post ids looks like.
const denial = $('Build Access Refusal').first().json;
const chatId = String(denial.telegram_chat_id || 'unknown');
const REPEAT_THRESHOLD = 3;
const WINDOW_MS = 60 * 60 * 1000;

// Note: workflow static data persists for production (trigger) executions only.
// In manual/pinned runs denial_count is always 1, so post denials do not alert.
const store = $getWorkflowStaticData('global');
if (!store.accessDenials || typeof store.accessDenials !== 'object') {
  store.accessDenials = {};
}
const now = Date.now();
for (const key of Object.keys(store.accessDenials)) {
  const kept = (store.accessDenials[key] || []).filter((ts) => now - ts < WINDOW_MS);
  if (kept.length) store.accessDenials[key] = kept;
  else delete store.accessDenials[key];
}
const recent = store.accessDenials[chatId] || [];
recent.push(now);
store.accessDenials[chatId] = recent;
const denial_count = recent.length;

const isUnknownChat = denial.refusal_reason === 'unknown_chat';
const shouldAlert = isUnknownChat || denial_count >= REPEAT_THRESHOLD;
if (!shouldAlert) {
  return [];
}

const update = $('Telegram Trigger').first().json || {};
const from = update.callback_query?.from || update.message?.from || {};
const chat = update.callback_query?.message?.chat || update.message?.chat || {};
const nameParts = [from.first_name, from.last_name].filter(Boolean);
const displayName = nameParts.length ? nameParts.join(' ') : (chat.title || 'unknown');
const username = from.username ? '@' + from.username : 'none';
const chatType = String(chat.type || 'unknown');

const OPEN = '<b>';
const CLOSE = '</' + 'b>';
const lines = [
  OPEN + 'XMonitor staging access denied' + CLOSE,
  'Workflow: Telegram Router Staging',
  'Reason: ' + denial.refusal_reason,
  'Chat id: ' + chatId,
  'Chat type: ' + chatType,
  'Name: ' + displayName,
  'Username: ' + username,
  'Intent: ' + (denial.intent || 'unknown'),
  'Post: ' + (denial.post_id || 'none'),
  'Caller clients: ' + ((denial.caller_client_ids || []).length ? denial.caller_client_ids.join(', ') : 'none'),
  'Caller is staff: ' + (denial.caller_is_staff ? 'yes' : 'no'),
  'Denials in last hour: ' + denial_count,
];
if (denial.refusal_reason === 'cross_tenant_post') {
  lines.push('Post owner client: ' + (denial.denied_post_client_id || 'unknown'));
}

return [{ json: { developer_chat_id: '8677383067', message: lines.join('\n'), denial_count } }];

// T5: merge the resolved client back onto the parsed /track payload, so one
// item carries both the accounts to track and the client that will own them.
// Fails closed: no row, or a row with a null client_id, means unresolved.
const parsed = $('Parse Users To Track').first().json;
const row = $input.first()?.json || {};

const client_id = String(row.client_id || '');
const track_client_resolved = client_id.length > 0;

const usernames = Array.isArray(parsed.usernames) ? parsed.usernames : [];
const client_name = String(row.client_name || '');

return [{
  json: {
    ...parsed,
    client_id,
    client_name,
    track_client_resolved,
    // Consumed by Build Access Refusal to distinguish an unknown client from
    // the T2 refusals, which must keep their existing messages verbatim.
    track_client_unresolved: !track_client_resolved,
    requested_client_slug: String(parsed.client_slug || ''),
    available_slugs: String(row.available_slugs || ''),
    // The success message names the client, so a mis-typed slug that happens
    // to resolve is still visible to the operator in the reply.
    message: `Now tracking for ${client_name} (${parsed.client_slug}):\n- ${usernames.join('\n- ')}`,
  },
  pairedItem: { item: 0 },
}];

// T5 /clients — render the client roster for a staff chat.
const rows = $input.all().map((i) => i.json).filter((r) => r && r.slug);

if (!rows.length) {
  return [{ json: { message: 'No clients exist yet. Create one with:\n/client_new <slug> <Name>' } }];
}

const lines = rows.map((r) => {
  const state = r.is_active ? '' : ' [inactive]';
  const chats = r.chat_ids ? r.chat_ids : 'no chats attached';
  return `• ${r.slug}${state} — ${r.name}\n   chats: ${chats}\n   min_replies ${r.min_replies}, threshold ${r.negative_threshold}`;
});

return [{ json: { message: `Clients (${rows.length}):\n\n${lines.join('\n\n')}` } }];

// T5 /client_new <slug> <Name...>
// The slug is the key staff will type into /track, so it is constrained to the
// shape /track accepts and lowercased here rather than at use time.
const route = $('Parse Telegram Message').first().json;
const args = String(route.command_args || '').trim();
const tokens = args.split(/\s+/).filter(Boolean);

const slug = String(tokens[0] || '').toLowerCase();
const name = tokens.slice(1).join(' ').trim();

let error = '';
if (!slug || !name) {
  error = 'Usage: /client_new <slug> <Name>\nExample: /client_new acme Acme Corporation';
} else if (!/^[a-z0-9][a-z0-9_-]{1,48}$/.test(slug)) {
  error = `"${slug}" is not a valid slug. Use 2-49 characters: lowercase letters, digits, hyphen or underscore, starting with a letter or digit.`;
}

return [{
  json: {
    client_new_valid: error === '',
    slug,
    client_name: name,
    message: error,
  },
}];

// T5 /client_new result. Names the next step explicitly — a client with no
// chat attached receives nothing, which is the easiest thing to forget.
const row = $input.first()?.json || {};

if (!row.client_id) {
  return [{ json: { message: 'Could not create the client. Check the slug and try again.' } }];
}

const created = row.created === true || row.created === 'true';
const head = created
  ? `Created client ${row.name} (${row.slug}).`
  : `Client ${row.slug} already exists — ${row.name}${row.is_active ? '' : ' [inactive]'}. Nothing changed.`;

return [{
  json: {
    message: `${head}\n\nNext:\n/client_attach ${row.slug} <chat_id>\n/track client:${row.slug} @handle`,
  },
}];

// T5 /client_attach <slug> <chat_id> [role] [label...]
// role defaults to 'client'; 'operator' is the only other value the
// Client Members_role_check constraint accepts.
const route = $('Parse Telegram Message').first().json;
const tokens = String(route.command_args || '').trim().split(/\s+/).filter(Boolean);

const slug = String(tokens[0] || '').toLowerCase();
const chat_id = String(tokens[1] || '');
let role = String(tokens[2] || '').toLowerCase();
let label = tokens.slice(3).join(' ').trim();

// role is optional and positional, so a label in its place must not become a role.
if (role && role !== 'client' && role !== 'operator') {
  label = [tokens[2], ...tokens.slice(3)].join(' ').trim();
  role = 'client';
}
if (!role) role = 'client';

let error = '';
if (!slug || !chat_id) {
  error = 'Usage: /client_attach <slug> <chat_id> [role] [label]\nExample: /client_attach acme 8677383067 client Acme ops';
} else if (!/^-?[0-9]{1,19}$/.test(chat_id)) {
  error = `"${chat_id}" is not a valid Telegram chat id.`;
}

return [{
  json: {
    client_attach_valid: error === '',
    slug,
    chat_id,
    role,
    label,
    message: error,
  },
}];

// T5 /client_attach result. An empty result means the slug matched no active
// client — the insert selected from an empty CTE — so it is reported as an
// unknown client, not as a silent success.
const row = $input.first()?.json || {};
const parsed = $('Parse Client Attach').first().json;

if (!row.client_id) {
  return [{
    json: {
      message: `No active client with slug "${parsed.slug}". Run /clients to see what exists, or create it with /client_new.`,
    },
  }];
}

return [{
  json: {
    message: `Attached chat ${row.chat_id} to ${row.client_name} (${parsed.slug}) as ${row.role}.\nAlerts: ${row.receives_alerts ? 'on' : 'off'}.\n\nNext:\n/track client:${parsed.slug} @handle`,
  },
}];

// Shared usage/validation error surface for the three client-admin commands.
// The message is built by whichever Parse node rejected the input.
return [{ json: { message: String($json.message || 'Invalid input.') } }];

// T5 follow-up: classify what the upsert actually did, per requested account.
//
// "Upsert Tracked X User" is guarded by
//   WHERE "Tracked Users".client_id = EXCLUDED.client_id
// so an account owned by ANOTHER client updates zero rows and the node emits an
// item with no user_id. That is the blocked-takeover case, and before this node
// existed it was indistinguishable from success.
//
// Index alignment: "If X User Lookup Successful" output 0 is exactly the set of
// items that reached the upsert, in the same order, so the two zip 1:1.
const attempts = $('Upsert Tracked X User').all();
const requested = $('If X User Lookup Successful').all();
const client = $('Build Track Client Result').first().json;

const succeeded = [];
const blocked = [];

attempts.forEach((item, i) => {
  const row = item.json || {};
  if (row.user_id) {
    succeeded.push({ user_id: String(row.user_id), username: String(row.username || '') });
    return;
  }
  const asked = requested[i]?.json?.data || {};
  blocked.push({ user_id: String(asked.id || ''), username: String(asked.username || '') });
});

return [{
  json: {
    client_id: String(client.client_id || ''),
    client_name: String(client.client_name || ''),
    client_slug: String(client.client_slug || ''),
    succeeded,
    blocked,
    succeeded_ids: succeeded.map((s) => s.user_id),
  },
}];

// T5 follow-up: report what actually happened, per account.
//
// A blocked account used to be silently reported as success. It is now named,
// because "already tracked by another client" is something only staff can
// resolve and they cannot resolve what they are not told.
const outcome = $('Build Track Outcome').first().json;
const deactivated = $input.all()
  .map((i) => i.json || {})
  .filter((r) => r.user_id);

const lines = [];

if (outcome.succeeded.length) {
  lines.push(`Now tracking for ${outcome.client_name} (${outcome.client_slug}):`);
  lines.push(outcome.succeeded.map((s) => `- ${s.username}`).join('\n'));
} else {
  lines.push(`No accounts were tracked for ${outcome.client_name} (${outcome.client_slug}).`);
  lines.push('Nothing was changed.');
}

if (deactivated.length) {
  lines.push('');
  lines.push('Stopped tracking:');
  lines.push(deactivated.map((r) => `- ${r.username || r.user_id}`).join('\n'));
}

if (outcome.blocked.length) {
  lines.push('');
  lines.push('Could not track — already tracked by another client:');
  lines.push(outcome.blocked.map((b) => `- ${b.username || b.user_id}`).join('\n'));
  lines.push('Move the account off its current client first, or track it there.');
}

return [{
  json: {
    message: lines.join('\n'),
    succeeded_count: outcome.succeeded.length,
    blocked_count: outcome.blocked.length,
    deactivated_count: deactivated.length,
  },
}];
